package com.shubhasai.monkeymart.analytics

import java.util.concurrent.atomic.AtomicInteger

/** Counts screen views per session so we can see which screens people actually use. */
object ScreenTracker {

    private val screenViews = AtomicInteger()

    /** Call from every Activity's onCreate. Only counts; never retains [screen]. */
    fun onScreenCreated(@Suppress("UNUSED_PARAMETER") screen: Any) {
        screenViews.incrementAndGet()
    }

    fun viewsThisSession(): Int = screenViews.get()
}

package com.shubhasai.monkeymart

import com.shubhasai.monkeymart.analytics.ScreenTracker
import com.shubhasai.monkeymart.data.Product
import com.shubhasai.monkeymart.ui.DealLoader
import java.lang.ref.WeakReference
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.CoroutineStart
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.cancelAndJoin
import kotlinx.coroutines.launch
import kotlinx.coroutines.runBlocking
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

class ScreenTrackerTest {

    private fun createScreens(): List<WeakReference<Any>> =
        List(3) { WeakReference(Any().also { ScreenTracker.onScreenCreated(it) }) }

    @Test
    fun countsScreensWithoutRetainingThem() {
        val before = ScreenTracker.viewsThisSession()
        val refs = createScreens()
        assertEquals(before + 3, ScreenTracker.viewsThisSession())

        repeat(5) {
            System.gc()
            Thread.sleep(20)
        }
        refs.forEach { assertNull("tracker leaked a screen", it.get()) }
    }
}

class DealLoaderTest {

    private val dealProduct = Product(1, "Banana Bunch", "x", 6_000, "d", 10)

    @Test
    fun cancelledLoadNeverShowsDialog() = runBlocking {
        val gate = CompletableDeferred<Product>()
        var loaded = false
        var dialogShown = false

        val job = launch(Dispatchers.Unconfined, start = CoroutineStart.DEFAULT) {
            DealLoader.load(
                productId = 1,
                fetch = { gate.await() },
                onLoaded = { loaded = true },
                showDeal = { dialogShown = true },
            )
        }
        job.cancelAndJoin()
        gate.complete(dealProduct)

        assertTrue(!loaded)
        assertTrue(!dialogShown)
    }

    @Test
    fun completedLoadShowsDealDialog() = runBlocking {
        var message: String? = null
        DealLoader.load(1, { dealProduct }, {}, { message = it })
        assertEquals("10% off Banana Bunch, today only.", message)
    }
}

